'use strict';
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',wallet:'<path d="M3 7V5a2 2 0 0 1 2-2h14v4M3 7h17a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H5a2 2 0 0 1-2-2V7Z"/><path d="M21 11h-6v5h6"/><circle cx="17" cy="13.5" r=".5"/>',file:'<path d="M14 3H5v18h14V8Z"/><path d="M14 3v5h5M8 12h8M8 16h6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',support:'<path d="M4 13v-2a8 8 0 0 1 16 0v2M4 12H2v6h4v-6Zm16 0h2v6h-4v-6ZM20 18v2l-5 1"/>',card:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 9h20M6 15h3m3 0h5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18M7 15h2m4 0h2"/>',chart:'<path d="M3 3v18h18M7 17v-5m5 5V7m5 10v-8"/>',heart:'<path d="M12 21 3.7 12.6A5.5 5.5 0 0 1 12 5.4a5.5 5.5 0 0 1 8.3 7.2Z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v6m0-10v.2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m4 12 5 5L20 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M3 16v5h18v-5"/>',settings:'<path d="m9 3-1 3-3 1-2 3 2 2-1 3 3 2 1 3 4 1 2-3 3-1 3-2-1-4 2-2-2-4-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',megaphone:'<path d="m3 10 18-5v14L3 14Zm3 5 1 6h4l-2-5M3 10v4"/>',edit:'<path d="m15 4 5 5M3 21l5-1L21 7l-4-4L4 16Z"/>',shield:'<path d="m12 3 9 4v5c0 6-9 10-9 10S3 18 3 12V7Z"/><path d="m8 12 3 3 5-6"/>',receipt:'<path d="M5 3v18l3-2 4 2 4-2 3 2V3l-3 2-4-2-4 2Z"/><path d="M9 10h6m-6 4h6"/>',up:'<path d="M12 20V4m-6 6 6-6 6 6"/>',down:'<path d="M12 4v16m-6-6 6 6 6-6"/>',shop:'<path d="M3 9 5 3h14l2 6v3H3ZM5 12v9h14v-9M9 21v-5h6v5"/>',location:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',eyeOff:'<path d="m3 3 18 18M10 5h2c6 0 10 7 10 7s-1 2-3 4M6 6c-3 2-4 6-4 6s4 7 10 7c2 0 4-1 5-2"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',switch:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3" fill="currentColor"/><circle cx="16" cy="17" r="3" fill="currentColor"/>'};
const icon=(name)=>`<svg class="i" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
const logo=()=>'<span class="logo"><img src="occci-logo.png" alt="OCCCI logo"></span>';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:2}).format(n);
const dateText=d=>new Date(d+'T12:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'});
const statusPill=s=>`<span class="pill ${/Pending|Submitted|review|Requested|Open/.test(s)?'pending':/Declined|Cancelled/.test(s)?'red':/Active|Scheduled/.test(s)?'blue':''}">${e(s)}</span>`;
const button=(label,action,cls='',ico='')=>`<button class="${cls}" onclick="${action}" ${!label?`aria-label="${ico==='close'?'Close dialog':ico==='menu'?'Open menu':'Refresh workspace'}"`: ''}>${ico?icon(ico):''}${label}</button>`;
const heading=(title,sub,actions='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${actions}</div>`;
const empty=(title,sub,action='',ico='file')=>`<div class="empty"><div class="iconbox">${icon(ico)}</div><h3>${title}</h3><p>${sub}</p>${action}</div>`;
const detail=(label,value)=>`<div class="detail"><dt>${label}</dt><dd>${value}</dd></div>`;

const defaultAvatars=[['man','Man'],['farmer','Farmer'],['lady','Lady'],['lola','Lola'],['boy','Boy'],['girl','Girl']];
function avatarArt(kind){
 const female=['lady','lola','girl'].includes(kind), child=['boy','girl'].includes(kind), gray=kind==='lola', hair=gray?'#b8c2ce':'#263955', shirt=({man:'#1766bf',farmer:'#31876b',lady:'#975aa2',lola:'#6655a0',boy:'#1695b1',girl:'#db7e65'})[kind]||'#1766bf';
 return `<svg viewBox="0 0 100 100" aria-hidden="true" class="avatar-art"><circle cx="50" cy="50" r="50" fill="#eaf1ff"/>${female?`<path d="M25 61V40c0-34 50-34 50 0v25Z" fill="${hair}"/>`:''}<path d="M13 100v-10c0-30 74-30 74 0v10" fill="${shirt}"/><path d="M43 61h14v15c-5 6-9 6-14 0" fill="#d99e77"/><ellipse cx="50" cy="43" rx="${child?20:21}" ry="25" fill="#edb58b"/><path d="M28 37c-3-32 46-35 45 0-9-2-18-11-22-15-4 9-14 13-23 15Z" fill="${hair}"/>${kind==='farmer'?'<path d="M26 29 33 12h34l7 17Z" fill="#e4b547"/><rect x="18" y="27" width="64" height="7" rx="3" fill="#f4cf69"/>':''}${kind==='girl'?'<circle cx="74" cy="28" r="8" fill="#ffcf21"/>':''}<circle cx="42" cy="44" r="2" fill="#243651"/><circle cx="58" cy="44" r="2" fill="#243651"/><path d="M44 56q6 5 12 0" fill="none" stroke="#925a48" stroke-width="2" stroke-linecap="round"/>${gray?'<g fill="none" stroke="#536b89" stroke-width="2"><circle cx="41" cy="45" r="7"/><circle cx="59" cy="45" r="7"/><path d="M48 45h4"/></g>':''}</svg>`;
}
function avatarPicker(selected='lady'){return `<fieldset class="avatar-fieldset full"><legend>Choose a temporary avatar</legend><div class="avatar-options">${defaultAvatars.map(([id,label])=>`<label class="avatar-option"><input type="radio" name="avatar" value="${id}" ${selected===id?'checked':''} required><span class="avatar-choice">${avatarArt(id)}</span><strong>${label}</strong></label>`).join('')}</div></fieldset>`;}
